        agg = None
        if parts[-1] in _GATE_AGG_FUNCS:
            agg = parts[-1]
            parts = parts[:-1]

def persist_answers(db: Any, state: Any, choices: list, *, content: Any = None) -> None:
    """Validate the entire envelope before writing. Same-body retries are idempotent."""
    requests = [canonical_choice(raw) for raw in choices]
    keys = [item["decision_key"] for item in requests]
    if len(set(keys)) != len(keys):
        raise ValueError("重复 decision_key")
    rows = {r["decision_key"]: r for r in db.get_rescript_desk_rows_by_keys(keys)}
    open_keys = {r["decision_key"] for r in db.list_rescript_desk(int(state.turn))}
    for choice in requests:
        row = rows.get(choice["decision_key"])
        if row is None:
            raise ValueError("decision_key 不在案头")
        if row["choice"]:
            if row["choice"] != choice:
                raise ValueError("已落批语不可改写")
            continue
        if choice["decision_key"] not in open_keys:
            raise ValueError("原案当前不可批")
        event_id = str(row.get("event_id") or "")
        action = choice.get("dossier_decision") or choice.get("action") or ""
        if event_id.startswith("dossier:"):
            legal = {o.get("dossier_decision") for o in row["options"]}
            if action not in legal:
                raise ValueError("打回旨须显式选择合法强颁、收回或留中")
        elif event_id.startswith("deliberation:"):
            if action not in {o.get("action") for o in row["options"]}:
                raise ValueError("无人站台案须显式选择御笔强推或留存")
        else:
            if action not in ({"", "midzhi"} if row["kind"] == "rescript_draft" else {""}):
                raise ValueError("批语不使用旧六动作；另旨·中旨只接急务原案")
            if not (choice.get("label", "").strip() or choice.get("note", "").strip()):
                raise ValueError("批语为空")
            if choice.get("label") and choice["label"] not in {o.get("label") for o in row["options"]}:
                raise ValueError("所选票拟不在原奏折中")
    with atomic_and_reload(db, state, content=content):
        order = int(db.conn.execute(
            "SELECT COALESCE(MAX(answer_order),0) FROM pending_decisions WHERE answered_turn=?", (int(state.turn),),
        ).fetchone()[0])
        for choice in requests:
            row = rows[choice["decision_key"]]
            if row["choice"]:
                continue
            order += 1
            db.conn.execute(
                "UPDATE pending_decisions SET choice_json=?, status='decided', answered_turn=?, answer_order=? "
                "WHERE turn=? AND idx=? AND kind=? AND status='pending'",
                (json.dumps(choice, ensure_ascii=False), int(state.turn), order,
                 row["source_turn"], row["idx"], row["kind"]),
            )
            event_id = str(row.get("event_id") or "")
            from ming_sim.month_chain import _DECREE_QUESTION_PREFIX, _WORLD_QUESTION_PREFIX
            if row["kind"] == "decision" and event_id and not event_id.startswith(
                ("dossier:", "deliberation:", _DECREE_QUESTION_PREFIX, _WORLD_QUESTION_PREFIX)
            ):
                db.record_event_decision_choice(state, event_id, choice, commit=False)

def effect_origin_rejection(self, origin_ref: str) -> Dict[str, object] | None:
    """Authorize extractor provenance immediately before a durable write.

    When apply_score_extraction arms ``_batch_authorized_open_affair_ids``,
    ``affair:<id>`` must also sit in that frozen batch set — one authority
    for every durable-effect carrier (fiscal included).
    """
    value = str(origin_ref or "").strip()
    valid = value == "盘面自发"
    unauthorized_batch = False
    if value.startswith("dossier:"):
        try:
            dossier_id = int(value.split(":", 1)[1])
            valid = dossier_id > 0 and self.get_decree_dossier(dossier_id) is not None \
                and self.dossier_authorizes_effects(dossier_id)
        except (OverflowError, TypeError, ValueError):
            valid = False
    elif value.startswith("affair:"):
        try:
            from ming_sim.entities.affair.store import (
                UnauthorizedAffairOriginRef,
                parse_origin_ref,
            )
            kind, affair_id = parse_origin_ref(value)
            if kind == "affair" and affair_id is not None:
                self.affairs.get(int(affair_id))
                authorized = getattr(self, "_batch_authorized_open_affair_ids", None)
                if authorized is not None and affair_id not in authorized:
                    valid = False
                    unauthorized_batch = True
                else:
                    valid = True
            else:
                valid = False
        except (KeyError, OverflowError, TypeError, ValueError):
            valid = False
    if valid:
        return None
    if unauthorized_batch:
        from ming_sim.entities.affair.store import UnauthorizedAffairOriginRef
        return {
            "rejected": True,
            # Distinct from missing/invalid existence — strategic preflight
            # must not envelope-fail this; apply paths still reject itemwise.
            "category": "unauthorized_affair_origin",
            "reason": str(UnauthorizedAffairOriginRef()),
        }
    return {
        "rejected": True,
        "category": "missing_origin_ref" if not value else "invalid_origin_ref",
        "reason": ("效果缺 origin_ref；盘面自然演化须显式标为「盘面自发」"
                   if not value else f"origin_ref 非法：{value}"),
    }

