def _apply_authority_change_item(
    db: GameDB, state: GameState, item: Dict[str, object],
) -> Dict[str, object]:
    """Apply one production-slot authority grant/revoke under the #611 contract."""
    if "dossier_id" not in item or item.get("dossier_id") in (None, ""):
        raise ValueError("missing_dossier_source")
    try:
        dossier_id = _parse_sqlite_id(item.get("dossier_id"))
    except (TypeError, ValueError):
        raise ValueError("missing_dossier_source") from None
    if dossier_id <= 0 or db.get_decree_dossier(dossier_id) is None:
        raise ValueError("missing_dossier_source")
    if not db.dossier_authorizes_effects(dossier_id):
        raise ValueError("dossier_not_effect_eligible")
    op = str(item.get("动作") or item.get("op") or "").strip()
    if op not in _AUTHORITY_GRANT_OPS | _AUTHORITY_REVOKE_OPS:
        raise ValueError("授权变更动作只收授予/收回")

    if op in _AUTHORITY_GRANT_OPS:
        holder_id = str(item.get("holder_id") or "").strip()
        privilege = str(item.get("privilege") or item.get("权项") or "").strip()
        scope = str(item.get("scope") or item.get("事域") or "").strip()
        if not holder_id or not privilege or not scope:
            raise ValueError("授予项必须含 holder_id/privilege/scope")
        if privilege not in AUTHORITY_PRIVILEGE_SET:
            raise ValueError("授权权项不在首批枚举")
        kind, separator, target_id = scope.partition(":")
        if not separator or not kind or not target_id:
            raise ValueError("invalid_authority_scope")
        if not db.conn.execute(
            "SELECT 1 FROM characters WHERE name=?", (holder_id,)
        ).fetchone():
            raise ValueError("授权对象不在人物档")
        origin = db.find_authority_by_origin(
            dossier_id, holder_id=holder_id, privilege=privilege, scope=scope,
        )
        if origin is not None:
            # Origin idempotency is independent of current applicability: a
            # revoked or expired grant remains the same durable authority row.
            return {
                "动作": "授予",
                "authority_id": int(origin["id"]),
                "dossier_id": dossier_id,
                "holder_id": holder_id,
                "privilege": privilege,
                "scope": scope,
                "reason": "same_dossier_replay",
            }
        effective_raw = item.get("effective_turn", item.get("生效回合"))
        expires_raw = item.get("expires_turn", item.get("失效回合"))
        effective_turn = (
            int(state.turn) if effective_raw in (None, "")
            else _parse_sqlite_id(effective_raw)
        )
        expires_turn = (
            None if expires_raw in (None, "")
            else _parse_sqlite_id(expires_raw)
        )
        if expires_turn is not None and expires_turn < effective_turn:
            raise ValueError("授权失效回合不得早于生效回合")
        existing = db.find_active_authority(
            state.turn, holder_id=holder_id, privilege=privilege, scope=scope,
        )
        if existing is not None:
            raise ValueError("duplicate_active_authority")
        cursor = db.conn.execute(
            "INSERT INTO authority_records "
            "(holder_id,privilege,scope,effective_turn,expires_turn,dossier_id) "
            "VALUES (?,?,?,?,?,?)",
            (
                holder_id, privilege, scope, effective_turn, expires_turn,
                dossier_id,
            ),
        )
        authority_id = int(cursor.lastrowid)
        return {
            "动作": "授予",
            "authority_id": authority_id,
            "dossier_id": dossier_id,
            "holder_id": holder_id,
            "privilege": privilege,

def _resolve_kind(obj: Mapping[str, Any]) -> Optional[str]:
    _ensure_catalog()
    kind = str(obj.get("kind") or "").strip()
    if kind in KNOWN_KINDS:
        return kind
    label = str(obj.get("动作类型") or "").strip()
    if label in LABEL_TO_KIND:
        return LABEL_TO_KIND[label]
    return None

def stopped_covert_effect(
    db: Any, *, origin_ref: object, beyond_intent: object = False,
) -> bool:
    """True only for a post-prohibition covert leg owned by the targeted old dossier."""
    origin = str(origin_ref or "").strip()
    if not origin.startswith("dossier:"):
        return False
    raw_id = origin.removeprefix("dossier:")
    if not raw_id.isdigit():
        return False
    from ming_sim.simulation import read_beyond_intent_raw
    beyond = db.coerce_beyond_intent_flag(read_beyond_intent_raw({"beyond_intent": beyond_intent}))
    if not beyond:
        return False
    return active_prohibition_dossier(db, int(raw_id)) is not None

def append_decree_dossier_participants(
    self, dossier_id: int, participants: Iterable[object], *,
    state: Optional[GameState] = None, commit: bool = True,
) -> List[Dict[str, object]]:
    """Append ADR 0053 roster entries without replacing durable members."""
    row = self.conn.execute(
        "SELECT participant_roster,action_type,decree_text FROM decree_dossiers WHERE id=?",
        (int(dossier_id),),
    ).fetchone()
    if row is None:
        raise KeyError(f"案卷不存在：{dossier_id}")
    try:
        existing_raw = json.loads(row["participant_roster"] or "[]")
    except (TypeError, ValueError):
        existing_raw = []
    existing = self._normalize_participant_roster(
        existing_raw if isinstance(existing_raw, list) else []
    )
    additions = self._normalize_participant_roster(participants, strict_structured=True)
    self._validate_participant_roster_references(additions)
    by_character = {str(item["character_id"]): item for item in existing}
    added: List[Dict[str, object]] = []
    for item in additions:
        character_id = str(item["character_id"])
        prior = by_character.get(character_id)
        if prior is not None:
            if prior != item:
                raise ValueError(f"参与人物已在案且机械档不同：{character_id}")
            continue
        by_character[character_id] = item
        added.append(item)
    merged = existing + added
    self._validate_dossier_delegations(merged)
    self._validate_participant_roster_references(merged)
    if added:
        archive_keys: set[str] = set()
        raw_keys_row = self.conn.execute(
            "SELECT office_archive_keys FROM decree_dossiers WHERE id=?",
            (int(dossier_id),),
        ).fetchone()
        raw_keys = (
            raw_keys_row["office_archive_keys"] if raw_keys_row is not None else None
        ) or "[]"
        parsed_keys = json.loads(raw_keys)
        if not isinstance(parsed_keys, list):
            raise ValueError(
                f"office_archive_keys 须为 JSON 数组：dossier {int(dossier_id)}"
            )
        archive_keys = {str(item) for item in parsed_keys}
        if str(row["action_type"] or "") != "secret_order":
            for item in added:
                if str(item.get("tier") or "") != "主办":
                    continue
                lead_name = str(item.get("character_id") or "")
                lead = self.conn.execute(
                    "SELECT office,office_type,location FROM characters WHERE name=?",
                    (lead_name,),
                ).fetchone()
                if lead is None:
                    continue
                key = self._office_archive_key(
                    lead["office"], lead["office_type"],
                    location=lead["location"] if "location" in lead.keys() else "",
                    character_name=lead_name,
                )
                if key:
                    archive_keys.add(key)
        self.conn.execute(
            "UPDATE decree_dossiers SET participant_roster=?,office_archive_keys=?,"
            "updated_at=CURRENT_TIMESTAMP WHERE id=?",
            (
                json.dumps(merged, ensure_ascii=False),
                json.dumps(sorted(archive_keys), ensure_ascii=False),
                int(dossier_id),
            ),
        )
        if state is not None and str(row["action_type"] or "") != "secret_order":
            for item in added:
                identity = ":".join(str(item.get(key) or "-") for key in (
                    "character_id", "tier", "role", "delegator_id",
                ))

def dossier_id_in_origin(origin: object) -> Optional[int]:
    text = str(origin or "")
    if not text.startswith("dossier:"):
        return None
    raw = text[len("dossier:"):].split(":", 1)[0]
    if not raw.isdigit():
        return None
    return int(raw)

