def _validate_event_dependency_graph_acyclic(content: GameContent, state: GameState) -> None:
    raw_graph: Dict[str, set[str]] = {
        ev.id: _event_dependency_ids(ev)
        for ev in [*content.events, *content.seed_events]
        if getattr(ev, "id", "")
    }
    graph = {eid: {dep for dep in deps if dep in raw_graph} for eid, deps in raw_graph.items() if deps}
    cache_key = tuple(sorted((eid, tuple(sorted(deps))) for eid, deps in graph.items()))
    if cache_key in _EVENT_DEPENDENCY_GRAPH_VALIDATION_CACHE:
        return

    visiting: set[str] = set()
    visited: set[str] = set()
    stack: List[str] = []

    def dfs(eid: str) -> None:
        if eid in visiting:
            cycle = stack[stack.index(eid):] + [eid] if eid in stack else [eid, eid]
            raise SettlementAbort(
                f"事件链依赖存在环：{' -> '.join(cycle)}",
                turn=state.turn,
                stage="event_chain_config",
            )
        if eid in visited:
            return
        visiting.add(eid)
        stack.append(eid)
        for dep in sorted(graph.get(eid, set())):
            dfs(dep)
        stack.pop()
        visiting.remove(eid)
        visited.add(eid)

    for eid in sorted(graph):
        dfs(eid)
    _EVENT_DEPENDENCY_GRAPH_VALIDATION_CACHE.add(cache_key)

def _pin_world_question_event_bindings(
    chain: Dict[str, Any], *, db: Any, state: Any, turn: int,
) -> None:
    """推送案头时把事件身份钉进月链（ADR 0115）。

    案头行身份保持 ``world-question:{turn}:{idx}``，后续问题顺延 idx，不把事件 id 写进那一列。
    事件身份只来自交接时请旨块自带、且属于当回合
    ``gather_fiscal_levy_petitions`` 快照的 event_id。只从 origin_ref 填进来的
    id 不是这份快照。没有这份身份的请旨保持非事件身份：剩余数量不能证明它属于
    某一到期事项，也不按标题猜配。钉完之后快照再变也不改这张表。
    """
    if isinstance(chain.get("world_question_event_bindings"), dict):
        return
    from ming_sim.issues import gather_fiscal_levy_petitions

    questions = [
        q for q in (chain.get("world_questions") or []) if isinstance(q, dict)
    ]
    due_set: set[str] = set()
    for ev in gather_fiscal_levy_petitions(state, db):
        event_id = str(ev.id or "").strip()
        if event_id:
            due_set.add(event_id)
    bindings: Dict[str, str] = {}
    used: set[str] = set()
    for idx, question in enumerate(questions):
        desk_key = f"{_WORLD_QUESTION_PREFIX}{turn}:{int(chain.get('world_question_offset', 0)) + idx}"
        echoed = str(question.get("event_id") or "").strip()
        origin_ref = str(question.get("origin_ref") or "").strip()
        if origin_ref and echoed == origin_ref:
            echoed = ""
        if echoed in due_set and echoed not in used:
            bindings[desk_key] = echoed
            used.add(echoed)
    chain["world_question_event_bindings"] = bindings

def prune_auto_saves(saves_dir: str, campaign_id: str, keep_turns: int = AUTO_SAVE_KEEP_TURNS) -> None:
    """清理自动存档：只清同一个 campaign_id，按 turn 分组，绝不碰手动存档。"""
    import os as _os
    import re as _re

    if not _os.path.isdir(saves_dir):
        return
    legacy_auto = _re.compile(rf"^{_re.escape(AUTO_SAVE_PREFIX)}\d{{4}}_\d{{2}}_t\d{{4}}_.+\.db$")
    for f in _os.listdir(saves_dir):
        if legacy_auto.match(f):
            try:
                _os.remove(_os.path.join(saves_dir, f))
            except OSError:
                pass
    campaign_id = (campaign_id or "").strip()
    if not campaign_id:
        return
    buckets: Dict[int, List[str]] = {}
    for f in _os.listdir(saves_dir):
        if not (f.startswith(f"{AUTO_SAVE_PREFIX}{campaign_id}_") and f.endswith(".db")):
            continue
        m = _re.search(r"_t(\d+)_", f)
        if not m:
            continue
        buckets.setdefault(int(m.group(1)), []).append(f)
    keep = max(1, int(keep_turns or 1))
    keep_turn_nums = set(sorted(buckets.keys(), reverse=True)[:keep])
    for turn_num, files in buckets.items():
        if turn_num in keep_turn_nums:
            continue
        for stale in files:
            try:
                _os.remove(_os.path.join(saves_dir, stale))
            except OSError:
                pass

