def resolve_dossier_owner_name(dossier: Mapping[str, object]) -> str:
    """案卷归属人：首名 canonical 主办，缺档时才读 legacy executor。

    #613 任别读端与 #625 监督事实底共调此单源；roster 解析禁止第三份遍历。
    缺档（无主办且无 executor）返回空串，由调用方按真除或缺席降级。
    """
    roster = dossier.get("participant_roster") or []
    if isinstance(roster, str):
        try:
            roster = json.loads(roster)
        except (TypeError, ValueError):
            # json.JSONDecodeError ⊂ ValueError
            roster = []
    if isinstance(roster, list):
        for entry in roster:
            if not isinstance(entry, dict):
                continue
            if str(entry.get("tier") or "").strip() != "主办":
                continue
            name = str(entry.get("character_id") or "").strip()
            if name:
                return name
    executor_id = str(dossier.get("executor_id") or "").strip()
    executor_kind = str(dossier.get("executor_kind") or "").strip()
    if executor_id and executor_kind in {"", "character"}:
        return executor_id
    return ""

def compose_report_origin(base: str, marks: Iterable[str] = ()) -> str:
    """结构化 origin：base[+mark...]。base 须已带 dossier-report: 前缀。"""
    cleaned = [str(m).strip() for m in marks if str(m or "").strip()]
    # 去重保序
    seen: Set[str] = set()
    ordered: List[str] = []
    for mark in cleaned:
        if mark in seen:
            continue
        seen.add(mark)
        ordered.append(mark)
    root = str(base or "").strip()
    if not ordered:
        return root
    return root + ORIGIN_MARK_SEP + ORIGIN_MARK_SEP.join(ordered)

